/**
 * @ohos/dsh-life — 小狮日记 · 人生之书，作为 dsh 工具。
 *
 * 为什么是插件不是工作区脚本：这台设备跑 tools.mode: native，run_code 不在
 * 模型工具表里，bash 又被 patch 移除。工作区里的 .js 是死文件。引擎必须随
 * 载荷分发，模型只通过三个工具调用它。
 *
 * 契约：
 *   · 所有数值、结局 id、标签都来自引擎；模型只负责把 digest 讲成一章。
 *   · 模型不能宣布“你后来发财了/你后悔了”，除非 digest 里有。
 *   · 每次 choose 都返回下一章/结局，不需要再调 status 补一次。
 */

import z from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'
import { HarnessError } from '@deepseek-ai/dsh-llm'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import { join } from 'node:path'

import {
  createSave,
  choose as choosePage,
  sceneOf,
  buildDigest,
  renderDigest,
  projection,
  DESIRE_LABELS,
  STAT_LABELS
} from './engine/life.js'

const name = 'tool-life'
const inject = ['tools', 'systemPrompt', 'workingDirectory']
const Config = z.object({})

const LIFE_DIR = '.life'
const SAVE_FILE = 'save.json'
const CARD_FILE = 'life.json'

var LifeError = class extends HarnessError {
  code
  constructor(message, code, options) {
    super(message, code, options)
    this.code = code
  }
}

async function resolveWorkdir(ctx, exec) {
  return exec.agent === void 0 ? process.cwd() : await ctx.workingDirectory.ensure(exec.agent, exec.signal)
}

let dataCache = null
async function loadData() {
  if (dataCache !== null) return dataCache
  const text = await readFile(join(import.meta.dirname, 'data', 'life.json'), 'utf8')
  dataCache = JSON.parse(text)
  return dataCache
}

async function loadSave(workdir) {
  try {
    const text = await readFile(join(workdir, LIFE_DIR, SAVE_FILE), 'utf8')
    return JSON.parse(text)
  } catch {
    return null
  }
}

async function commit(workdir, state) {
  const data = await loadData()
  const dir = join(workdir, LIFE_DIR)
  await mkdir(dir, { recursive: true })
  const tmp = join(dir, `${SAVE_FILE}.${process.pid}.tmp`)
  await writeFile(tmp, JSON.stringify(state), 'utf8')
  await rename(tmp, join(dir, SAVE_FILE))
  await writeFile(join(dir, CARD_FILE), JSON.stringify(projection(state, data)), 'utf8')
  return { state, data }
}

function formatEffects(effects) {
  return Object.entries(effects ?? {})
    .filter(([, value]) => Number.isFinite(value) && value !== 0)
    .map(([key, value]) => `${STAT_LABELS[key] ?? key} ${value > 0 ? '+' : ''}${value}`)
    .join('　')
}

function renderScene(state, data) {
  const scene = sceneOf(state, data)
  if (scene.finished === true) {
    return `【结局】${scene.ending.title}\n${scene.ending.text}\n\n${scene.ending.comment}`
  }
  const lines = [
    renderDigest(buildDigest(state, data)),
    '',
    `【${scene.title}】`,
    scene.narration,
    '',
    ...scene.options.map((option) =>
      `· ${option.label}（${option.desireLabel}${option.canon ? ' · 当年' : ' · 如果'}）` +
      `${option.note.length > 0 ? `——${option.note}` : ''}`
    )
  ]
  return lines.join('\n')
}

function registerNew(ctx) {
  const tool = defineTool({
    name: 'life_new',
    description:
      '开始一本新的《如果》（小狮日记·人生之书）（玩家扮演小狮，18 岁，2016 年，临江）。' +
      '会覆盖同一工作区里已有的存档。只在玩家明确说“开始/重开”时调用。' +
      '开局后必须用返回的 digest 和章节叙述描述处境，不要自行编造数值。',
    parameters: {
      name: { type: 'string', description: '存档名；同名会得到同一本初始状态。缺省 xiaoshi。' }
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const data = await loadData()
      const state = createSave(args?.name)
      await commit(workdir, state)
      return {
        digest: buildDigest(state, data),
        scene: sceneOf(state, data),
        rendered: renderScene(state, data)
      }
    }
  })
  ctx.tools.register(tool)
}

function registerStatus(ctx) {
  const tool = defineTool({
    name: 'life_status',
    description:
      '读取当前《如果》的处境：年份、年龄、第几章、六个数值、城市/学校/工作/伴侣、' +
      '欲望账本、当前章节与选项。不改变任何状态。玩家问“我现在怎么样”“我走到哪了”时用它。',
    parameters: {},
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(_args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const data = await loadData()
      const state = await loadSave(workdir)
      if (state === null) {
        throw new LifeError('还没有开局。先调用 life_new 开始这一生。', 'LIFE_NO_SAVE')
      }
      return {
        digest: buildDigest(state, data),
        scene: sceneOf(state, data),
        rendered: renderScene(state, data)
      }
    }
  })
  ctx.tools.register(tool)
}

function registerChoose(ctx) {
  const tool = defineTool({
    name: 'life_choose',
    description:
      '在当前章节里选一个已声明的选项（用 life_status/life_new 返回的 option id，不是序号）。' +
      '引擎会结算六个数值、记欲望账本、翻到下一章或结局。' +
      '严禁在返回结果之外补充任何数值、结局或人物后果。',
    parameters: {
      option: {
        type: 'string',
        required: true,
        description: '选项 id（例如 finance / archaeology / repeat），不是序号。'
      }
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          outcome: { type: 'json', required: true },
          digest: { type: 'json', required: true },
          scene: { type: 'json', required: true },
          rendered: { type: 'string', required: true }
        }
      },
      render: (_args, value) => [{ type: 'text', text: value.rendered }]
    },
    async execute(args, exec) {
      const workdir = await resolveWorkdir(ctx, exec)
      const data = await loadData()
      const state = await loadSave(workdir)
      if (state === null) {
        throw new LifeError('还没有开局。先调用 life_new 开始这一生。', 'LIFE_NO_SAVE')
      }
      const result = choosePage(state, data, args?.option)
      await commit(workdir, result.state)
      const scene = sceneOf(result.state, data)
      const lines = [
        `【已选】${result.option.label}`,
        result.option.note ?? '',
        formatEffects(result.effects),
        result.state.finished === true
          ? ''
          : `【下一章】${scene.title}`,
        scene.finished === true
          ? `【结局】${scene.ending.title}\n${scene.ending.text}\n${scene.ending.comment}`
          : scene.narration
      ].filter((line) => line.length > 0)
      return {
        outcome: {
          label: result.option.label,
          desire: DESIRE_LABELS[result.option.desire] ?? result.option.desire,
          effects: result.effects,
          finished: result.state.finished,
          ending: scene.finished === true ? scene.ending : null
        },
        digest: buildDigest(result.state, data),
        scene,
        rendered: lines.join('\n')
      }
    }
  })
  ctx.tools.register(tool)
}

function apply(ctx, _config) {
  registerNew(ctx)
  registerStatus(ctx)
  registerChoose(ctx)
}

export { name, inject, Config, apply }
